impl RelayLimits {
    pub(super) fn new(
        count: u64,
        slack: u64,
        bytes: u64,
        byte_slack: u64,
    ) -> Result<Self, LogError> {
        Ok(Self {
            count,
            bytes,
            envelope_count: count
                .checked_add(slack)
                .ok_or(LogError::RepositoryCounterExhausted)?,
